P = [
 dict(pmid='43054150', doi='10.3389/fpubh.2026.1911782', journal='Front Public Health', title='Spatially autocorrelated and clustered associations between short-term exposure to PM(2.5) and daily reported confirmed COVID-19 cases across the contiguous United States, 2020-2022.', tier='B', basis='Not stated', short='Contiguous US: PM2.5-COVID-19 case RR 1.034 per 10 ug/m3 pooled, four spatial clusters up to 1.177; 2.06% of cases attributed', design='Multi-city time-series + random-effects meta-analysis', pm='Daily PM2.5 per 10 ug/m3 (data source and lag not in abstract)', geo='USA (contiguous)', endpoint='Daily reported confirmed COVID-19 cases', affil='West China School of Public Health, Sichuan University, China; West China School of Public Health, Sichuan University, China', n='Three-stage analysis across the contiguous United States: location-specific GAMs for daily PM2.5 and confirmed COVID-19 cases, then an estimation-error-based scan statistic and multivariate conditional meta-autoregression for spatial autocorrelation and clustering. Associations were heterogeneous (I2 67%), strongly autocorrelated (rho 0.972) and formed four clusters. Pooled RR per 10 ug/m3 was 1.0341 (95% CI 1.0308-1.0375); cluster RRs ranged from 1.0005 (0.9984-1.0026) to 1.1770 (1.1551-1.1992). About 1.76 million cases (2.06%) to June 2022 were attributed to PM2.5 above the WHO guideline. Weakness: reported cases depend on testing intensity, which co-varies with season and urbanicity; PM2.5 source and lag are not given; attribution assumes causality. Relevance: low for sensing, though the clustering method could transfer to heterogeneous network-based estimates.', sub=corpus.RESP),
 dict(pmid='43053797', doi='10.1093/ajeadv/uuag013', journal='AJE Adv', title='A case of the Mondays? Pollution exposure and delayed care in pediatric asthma hospitalizations.', tier='B', basis='Not stated', short='Illinois Medicaid 4.5M ZIP-days: lag 0-1 PM2.5 linked to paediatric asthma admission only on Mondays - care-seeking timing confounds lags', design='Ecological panel, fixed effects', pm='Daily ZIP-code PM2.5, lag 0-1 moving average and longer windows (source not in abstract)', geo='USA (Illinois)', endpoint='Paediatric asthma hospitalisation probability (Medicaid)', affil='Southern Illinois University School of Medicine, USA; Southern Illinois University School of Medicine, USA', n='More than 4.5 million ZIP-code-day observations from Illinois Medicaid, 2012-2021, linking paediatric asthma hospitalisations to daily PM2.5 and meteorology in fixed-effects logistic models, with day of week as covariate and effect modifier. Lag 0-1 PM2.5 was associated with hospitalisation probability on Mondays only; PM2.5 was higher at weekends while admissions peaked early in the week, and longer exposure windows attenuated weekday-specific associations. The abstract gives no effect sizes or CIs. Weakness: admission date is partly an access outcome, so a Monday pattern can arise from delayed presentation of weekend exacerbations; the PM2.5 source is not stated. Relevance: lag structure in short-term studies is contaminated by care-seeking rhythm; symptom diaries with personal monitors would separate onset from presentation.', sub=corpus.RESP),
 dict(pmid='43052767', doi='10.1186/s12873-026-01744-z', journal='BMC Emerg Med', title='Associations of ambient temperature and PM2.5 concentration with temporal variability in emergency department visits for acute gastrointestinal illnesses in central Bangkok, Thailand: a 5-year retrospective analysis.', tier='C', basis='Not stated', short='Bangkok single-hospital 2018-2023: GI emergency visits rise above 139.8 ug/m3 PM2.5, amplified by heat index (no estimates in abstract)', design='Time-series (distributed lag non-linear)', pm='Daily PM2.5 with heat index (data source not in abstract)', geo='Thailand', endpoint='Emergency department visits for gastritis and gastroenteritis', affil='NYU Grossman School of Medicine, USA; Chulalongkorn University, Thailand', n="Single-hospital time series of emergency visits for gastritis and gastroenteritis in Bangkok, 2018-2023, with heat index and daily PM2.5 in GAMs and distributed-lag non-linear models, plus stratified interaction analyses. Higher heat index and PM2.5 were associated with more GI visits; risk rose only above 139.8 ug/m3 relative to the mean daily level, and stratification suggested heat amplifies the PM2.5 association; heat index below 30 C was protective. The abstract gives no RRs or CIs. Weakness: one hospital catchment, a threshold in the extreme tail reached on few days, and no described control for seasonal infectious gastroenteritis; an inhaled-PM mechanism for GI illness is speculative. Relevance: low-moderate; Bangkok's episodic peaks suit network-resolved exposure for ED-level studies.", sub=corpus.OTHR),
 dict(pmid='43056800', doi='10.1016/j.gaceta.2026.102676', journal='Gac Sanit', title='[Air pollution and cancer mortality in municipalities of the Valparaiso Region, Chile (2009-2019)].', tier='C', basis='Reference / regulatory monitor', short='Valparaiso Region 2009-2019 ecological: PM10 with all-cancer mortality in Quintero, PM2.5 with stomach cancer in Vina del Mar', design='Observational - ecological', pm='Annual PM2.5, PM10 and SO2 from the national air-quality monitoring system, five municipalities', geo='Chile (Valparaiso Region)', endpoint='Age-standardised all-cancer and stomach-cancer mortality', affil='Universidad de Chile, Chile; Universidad de Chile, Chile', n='Ecological time series for five Valparaiso Region municipalities, 2009-2019: annual SO2, PM2.5 and PM10 from the national monitoring system against age-standardised all-cancer and stomach-cancer mortality, municipality-specific Prais-Winsten models adjusting for trend and autocorrelation. Positive coefficients were isolated: PM10 with all-cancer mortality in Quintero (beta 2.81, 95% CI 1.05-4.57), PM2.5 with stomach-cancer mortality in Vina del Mar (0.55, 0.22-0.88), SO2 with stomach cancer in Catemu (0.62, 0.28-0.96); PM10 also with both outcomes among Quintero men. Weakness: eleven annual points per municipality, many municipality x pollutant x outcome tests, no latency, ecological confounding, and beta units not given. Relevance: Quintero is an industrially impacted zone where sparse regulatory monitoring is the binding constraint on exposure-response work.', sub=corpus.OTHR),
]
